<?php
require_once __DIR__.'/bootstrap.php';require_admin();$pageTitle='Kích thước';$active='sizes';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);try{if(($_POST['action']??'')==='delete'){$pdo->prepare("DELETE FROM kichthuoc WHERE id=?")->execute([$id]);flash('success','Đã xóa kích thước.');}else{$name=strtoupper(trim((string)($_POST['ten_size']??'')));$order=(int)($_POST['thu_tu']??0);$status=(int)($_POST['trang_thai']??1);if($name==='')throw new RuntimeException('Tên size là bắt buộc.');if($id)$pdo->prepare("UPDATE kichthuoc SET ten_size=?,thu_tu=?,trang_thai=? WHERE id=?")->execute([$name,$order,$status,$id]);else $pdo->prepare("INSERT INTO kichthuoc (ten_size,thu_tu,trang_thai) VALUES (?,?,?)")->execute([$name,$order,$status]);flash('success','Đã lưu kích thước.');}}catch(Throwable $e){flash('error',$e instanceof PDOException?'Không thể lưu/xóa. Size có thể trùng hoặc đang được biến thể sử dụng.':$e->getMessage());}redirect('sizes.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM kichthuoc WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query("SELECT k.*,COUNT(b.id) AS so_bien_the FROM kichthuoc k LEFT JOIN bien_the_sanpham b ON b.kich_thuoc_id=k.id GROUP BY k.id ORDER BY k.thu_tu,k.id")->fetchAll();require __DIR__.'/admin-header.php';?>
<div class="form-grid"><section class="panel"><h2><?=$edit?'Sửa size':'Thêm kích thước'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="field" style="margin-top:18px"><label>TÊN SIZE *</label><input name="ten_size" required value="<?=e($edit['ten_size']??'')?> " placeholder="S, M, L, XL"></div><div class="field" style="margin-top:15px"><label>THỨ TỰ HIỂN THỊ</label><input type="number" name="thu_tu" value="<?=e($edit['thu_tu']??0)?>"></div><div class="field" style="margin-top:15px"><label>TRẠNG THÁI</label><select name="trang_thai"><option value="1" <?=((int)($edit['trang_thai']??1)===1)?'selected':''?>>Hoạt động</option><option value="0" <?=((int)($edit['trang_thai']??1)===0)?'selected':''?>>Ẩn</option></select></div><div class="form-actions"><button class="btn">Lưu kích thước</button><a class="btn light" href="sizes.php">Làm mới</a></div></form></section><section class="panel"><h2>Thứ tự đề xuất</h2><p class="muted">S, M, L, XL, XXL. Có thể dùng số đo riêng nếu cửa hàng cần bảng size tùy chỉnh.</p></section></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Size</th><th>Thứ tự</th><th>Biến thể</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['ten_size'])?></strong></td><td><?=$r['thu_tu']?></td><td><?=$r['so_bien_the']?></td><td><span class="badge <?=((int)$r['trang_thai']===1)?'':'off'?>"><?=((int)$r['trang_thai']===1)?'Hoạt động':'Ẩn'?></span></td><td><div class="actions"><a class="btn small light" href="?edit=<?=$r['id']?>">Sửa</a><form class="inline" method="post" onsubmit="return confirm('Xóa size này?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn small danger">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/admin-footer.php';?>
